-- 022 (2026-10-18): Pay Dig Sites directory (public read, admin-only write) + merch categories with "Coming soon" Complete Kits.
-- Rollback: 022_paydig_kits_down.sql
begin;
create table if not exists public.pay_dig_sites (
  slug text primary key, name text not null, state text not null, area text not null, type text not null check (type in ('Fossils', 'Minerals & Gems', 'Mixed')),
  finds text, fee_note text not null default 'See operator site', url text not null check (url ~ '^https?://'), status_note text, source_url text not null check (source_url ~ '^https?://'),
  last_verified date not null default current_date, sort int not null default 1000, active boolean not null default true, updated_at timestamptz not null default now());
alter table public.pay_dig_sites enable row level security;
drop policy if exists "pay dig read" on public.pay_dig_sites; create policy "pay dig read" on public.pay_dig_sites for select using (active or public.is_admin());
drop policy if exists "pay dig admin write" on public.pay_dig_sites; create policy "pay dig admin write" on public.pay_dig_sites for all using (public.is_admin()) with check (public.is_admin());
revoke all on public.pay_dig_sites from anon; grant select on public.pay_dig_sites to anon; grant select, insert, update, delete on public.pay_dig_sites to authenticated;
drop trigger if exists pay_dig_touch on public.pay_dig_sites; create trigger pay_dig_touch before update on public.pay_dig_sites for each row execute function public.touch_updated_at();
on conflict (slug) do update set name=excluded.name,state=excluded.state,area=excluded.area,type=excluded.type,finds=excluded.finds,fee_note=excluded.fee_note,url=excluded.url,status_note=excluded.status_note,source_url=excluded.source_url,last_verified=excluded.last_verified,sort=excluded.sort;
-- merch: category + coming_soon (no price, no checkout). Kits are drafts of future products only.
alter table public.products add column if not exists category text not null default 'apparel', add column if not exists coming_soon boolean not null default false;
select v.name, v.descr, 0, 'usd', jsonb_build_array(v.img), '[]'::jsonb, true, v.sort, 'kits', true from (values
 ('Rockhounding Starter Kit', 'Rock hammer, safety glasses, work gloves, 10x loupe, sample bags and a field guide card with a QR code to the UnEarthed Finds app.', 'assets/img/kits/rockhounding.svg', 100),
 ('Archaeology / Artifact Field Kit', 'Photo scale, calipers and measuring tape, soft brushes, labeled find bags and a field notebook, plus app quick-start for cataloging.', 'assets/img/kits/archaeology.svg', 110),
 ('Fossil Prep / Cleaning Kit', 'Dental picks, soft brushes, consolidant how-to notes and padded storage boxes for prepared specimens.', 'assets/img/kits/fossil-prep.svg', 120),
 ('Kids Discovery Kit', 'Kid-sized tools, safety glasses, a magnifier and activity ideas for first finds.', 'assets/img/kits/kids.svg', 130)) v(name, descr, img, sort)
where not exists (select 1 from public.products p where p.category = 'kits' and p.name = v.name);
commit;
